import {RelayEnvironmentProvider, relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'

import {IssueTypesMutationErrorsProvider} from '../contexts/IssueTypesMutationErrorsContext'
import {OrganizationIssueTypesSettings} from './OrganizationIssueTypesSettings'

export function IndexPage() {
  // this package is no longer using Relay directly but it uses the IssueFieldPicker component that uses Relay
  const relayEnvironment = relayEnvironmentWithMissingFieldHandlerForNode()

  return (
    <RelayEnvironmentProvider environment={relayEnvironment}>
      <IssueTypesMutationErrorsProvider>
        <OrganizationIssueTypesSettings />
      </IssueTypesMutationErrorsProvider>
    </RelayEnvironmentProvider>
  )
}
