import type {IssueField} from '@github-ui/issue-fields-shared/issue-field'
import {mainQuery} from '@github-ui/react-core/future/main-query'

import {issueTypesSettingsAppBuilder} from '../config/app-builder'
import type {IssueType} from '../types/issue-type'
import type {IssueTypesSettingsIndexResponse} from './index-route'

export type IssueTypesSettingsEditResponse = IssueTypesSettingsIndexResponse & {
  issueType: IssueType
  pinnedIssueFields: IssueField[]
  pinnedIssueFieldsEnabled: boolean
}

export const issueTypesSettingsEditRouteId = 'issueTypesSettingsEditRoute'
export const issueTypesSettingsEditRoute = issueTypesSettingsAppBuilder.createQueryRouteConfig(
  issueTypesSettingsEditRouteId,
  {
    path: '/organizations/:organization_id/settings/issue-types/:id',
    queries: [mainQuery<IssueTypesSettingsEditResponse>()],
  },
)
