import {FormControl, TextInput} from '@primer/react'

import {Resources} from '../constants/strings'
import styles from './TypeDescription.module.css'

type TypeDescriptionProps = {
  disabled?: boolean
  description: string
  error: string
  setDescription: (name: string) => void
  setError: (error: string) => void
  ref?: React.Ref<HTMLInputElement>
}

export function TypeDescription({
  ref: forwardedRef,
  error,
  setError,
  description,
  setDescription,
  disabled = false,
}: TypeDescriptionProps) {
  return (
    <FormControl disabled={disabled} className={styles.TypeDescriptionFormControl}>
      <FormControl.Label>{Resources.descriptionLabel}</FormControl.Label>
      <TextInput
        value={description}
        onChange={e => {
          setError('')
          setDescription(e.target.value)
        }}
        placeholder={Resources.descriptionPlaceholder}
        name="description"
        data-testid="issue-type-description"
        validationStatus={error ? 'error' : undefined}
        ref={forwardedRef}
        className={styles.descriptionInput}
      />
      {error && <FormControl.Validation variant="error">{error}</FormControl.Validation>}
    </FormControl>
  )
}
