import {Heading} from '@primer/styled-react'
import {clsx} from 'clsx'
import type {FC, ReactNode} from 'react'

import styles from './Title.module.css'

type TitleProps = {
  children: ReactNode
  showBorder?: boolean
  page?: string
  className?: string
}

export const Title: FC<TitleProps> = ({children, page, showBorder = true, className}) => {
  const border = showBorder
    ? {
        borderBottomStyle: 'solid',
        borderBottomColor: 'border.muted',
        borderBottomWidth: '1px',
      }
    : {}
  return (
    <Heading
      as="h2"
      id={`issue-types-heading${page ? `-${page}` : ''}`}
      sx={{
        ...border,
      }}
      className={clsx(styles.TitleHeading, className)}
    >
      {children}
    </Heading>
  )
}
